8: /// Production M11 canvas/content, without any source/controller/window operation.
9: @main enum ProgressQuantityPreview {
10:     enum Failure: Error { case check(String) }
11:     static func rect(_ r: NSRect) -> [String: Double] { ["x": r.minX, "y": r.minY, "width": r.width, "height": r.height] }
12:     @MainActor static func main() async {
13:         _ = NSApplication.shared; NSApp.setActivationPolicy(.prohibited)
14:         let out = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
15:         do {
16:             try FileManager.default.createDirectory(at: out, withIntermediateDirectories: true)
17:             var frames: [[String: Any]] = []
18:             for parent in [NSAppearance.Name.aqua, .darkAqua] {
19:                 for sample in ["zero", "percent", "complete-value", "count", "large-count", "huge-count", "indeterminate", "unknown", "paused", "ended", "stale", "long", "three"] {
20:                     let windows = 0
21:                     let ongoing = sample == "three" ? 3 : 1
22:                     var tiles = [NotchTile]()
23:                     for index in 0..<ongoing {
24:                         let quantity: NotchActivity.Quantity
25:                         switch sample {
26:                         case "zero": quantity = .fraction(0)
27:                         case "complete-value", "ended": quantity = .fraction(1)
28:                         case "count": quantity = .count(2,9)
29:                         case "large-count": quantity = .count(999,1000)
30:                         case "huge-count": quantity = .count(999999,1000000)
31:                         case "indeterminate": quantity = .indeterminate
32:                         case "unknown": quantity = .unknown
33:                         case "three": quantity = index == 0 ? .fraction(0.42) : (index == 1 ? .count(2,9) : .indeterminate)
34:                         default: quantity = .fraction(0.42)
35:                         }
36:                         guard quantity.isValid else {throw Failure.check("valid fixture quantity")}
37:                         let subtitle = sample == "long" ? "WindowShade_设计评审_最终材料_" + String(repeating:"外观与动作检查", count:12) + ".zip" : "演示材料.zip"
38:                         var item = NotchActivity(id:"qa-progress-\(index)",kind:.download,title:"正在下载",subtitle:subtitle,symbol:"arrow.down.circle",startedAt:0,progress:quantity,isPaused:sample == "paused",sessionPhase:nil)
39:                         item.isStale = sample == "stale"
40:                         if sample == "ended" {item.endedAt = 1}
41:                         guard let cell = NotchRow.ongoingCells(from:[item]).first else {throw Failure.check("actual Core projection")}
42:                         let value = NotchTile.Ongoing(activityID:cell.activityID,subtitle:cell.subtitle,symbol:cell.symbol,phase:cell.phase,isPaused:cell.isPaused,quantity:cell.quantity,quantityText:cell.quantityText,spoken:cell.spoken,action:cell.action,closesRow:cell.closesRow,accessory:cell.accessory,isStale:cell.isStale,isEnded:cell.isEnded)
43:                         tiles.append(NotchTile(id:UInt32(850+index),kind:.activity,snapshot:nil,icon:nil,title:cell.title,waiting:false,ongoing:value))
44:                     }
45:                     let layout = NotchRow.layout(windows: windows, ongoing: ongoing)
46:                     let width = max(185 + 120, layout.islandWidth(minimum: 0))
47:                     let height = 33.5 + NotchIsland.peninsulaContentHeight(142)
48:                     let bounds = NSRect(x: 0, y: 0, width: width, height: height)
49:                     let canvas = NotchCanvasView(frame: bounds)
50:                     let window = NSWindow(contentRect: bounds, styleMask: [.borderless], backing: .buffered, defer: false)
51:                     window.isReleasedWhenClosed = false; window.alphaValue = 0
52:                     window.appearance = NSAppearance(named: parent); window.contentView = canvas
53:                     window.setFrame(NSRect(x: -8000, y: -8000, width: width, height: height), display: false)
54:                     let content = NotchCanvasView.Content(tiles: tiles, dots: 0, dotsChanged: false, dotsY: 0,
55:                         compact: nil, compactSlots: nil, alert: nil, hint: nil, notchHeight: 33.5)
56:                     var completions = 0
57:                     canvas.morph(to: bounds, style: .init(cornerRadius: 28, allCorners: false, fill: .black, border: 1),
58:                         content: content, spring: nil) { completions += 1 }
59:                     canvas.layoutSubtreeIfNeeded(); try await Task.sleep(nanoseconds: 150_000_000); canvas.layoutSubtreeIfNeeded()
60:                     var actual: [[String: Any]] = []
61:                     func visit(_ view: NSView) {
62:                         if let tile = view as? NotchTileView, !tile.isHiddenOrHasHiddenAncestor {
63:                             guard let payload = Mirror(reflecting: tile).children.first(where: { $0.label == "tile" })?.value as? NotchTile else { return }
64:                             var record: [String: Any] = ["id": tile.tileID, "frame": rect(tile.convert(tile.bounds, to: canvas)),
65:                                 "title": payload.title, "kind": String(describing: payload.kind), "dark": tile.effectiveAppearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua,
66:                                 "accessibility": tile.accessibilityLabel() ?? ""]
67:                             if let value = payload.ongoing {
68:                                 record["subtitle"] = value.subtitle; record["quantity"] = String(describing: value.quantity)
69:                                 record["quantityText"] = value.quantityText as Any? ?? NSNull()
70:                                 record["stale"] = value.isStale; record["ended"] = value.isEnded
71:                                 record["shelf"] = value.shelfCount as Any? ?? NSNull()
72:                                 record["drawing"] = String(describing:value.quantity.drawing)
73:                                 record["paused"] = value.isPaused
74:                                 record["accessibilityValue"] = tile.accessibilityValue() as Any? ?? NSNull()
75:                                 record["tooltip"] = tile.toolTip as Any? ?? NSNull()
76:                                 let font = NSFont.monospacedDigitSystemFont(ofSize:10.5,weight:.semibold)
77:                                 let rounded = font.fontDescriptor.withDesign(.rounded).flatMap {NSFont(descriptor:$0,size:font.pointSize)} ?? font
78:                                 record["naturalQuantityWidth"] = NSAttributedString(string:value.quantityText ?? "",attributes:[.font:rounded]).size().width
79:                                 if let part = Mirror(reflecting:tile).children.first(where:{$0.label == "part"})?.value as? NotchProgressPartLayers {
80:                                     record["partHidden"] = part.root.isHidden
81:                                     record["partFrame"] = rect(part.root.frame)
82:                                     record["partQuantity"] = String(describing:part.model.quantity)
83:                                     record["layerChildren"] = (part.root.sublayers ?? []).map {layer -> [String:Any] in
84:                                         var entry: [String:Any] = ["hidden":layer.isHidden,"animations":layer.animationKeys() ?? []]
85:                                         if let shape=layer as? CAShapeLayer {entry["strokeEnd"]=shape.strokeEnd}
86:                                         return entry
87:                                     }
88:                                 }
89:                             }
90:                             actual.append(record)
91:                         }
92:                         view.subviews.forEach(visit)
93:                     }
94:                     visit(canvas)
95:                     guard actual.count == tiles.count, completions == 1, !window.isVisible, !NSApp.isActive,
96:                         window.alphaValue == 0, NSScreen.screens.allSatisfy({ !window.frame.intersects($0.frame) }) else { throw Failure.check("actual tiles/host") }
97:                     let name = "\(parent == .aqua ? "light" : "dark")-\(sample)"
98:                     guard let bitmap = canvas.bitmapImageRepForCachingDisplay(in: canvas.bounds) else { throw Failure.check("bitmap") }
99:                     canvas.cacheDisplay(in: canvas.bounds, to: bitmap)
100:                     guard let png = bitmap.representation(using: .png, properties: [:]) else { throw Failure.check("png") }
101:                     try png.write(to: out.appendingPathComponent(name + ".png"))
102:                     frames.append(["name": name, "sample": sample, "windows": windows, "ongoing": ongoing,
103:                         "width": width, "height": height, "tiles": actual, "completions": completions,
104:                         "canvasDark": canvas.effectiveAppearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua,
105:                         "visible": window.isVisible, "active": NSApp.isActive, "alpha": window.alphaValue])
106:                     window.contentView = nil; window.close()
107:                 }
108:             }
109:             try JSONSerialization.data(withJSONObject: ["frames": frames, "sourceControllers": 0, "actions": 0], options: [.prettyPrinted, .sortedKeys]).write(to: out.appendingPathComponent("frames.json"))
110:             print("PASS \(frames.count) actual progress quantity static frames; no source/controllers/actions")
111:         } catch { fputs("FAIL \(error)\n", stderr); exit(1) }
112:     }
113: }
